\ = Get-Content -LiteralPath 'frontend\src\app\dashboard\businesses\[id]\inbox\page.tsx' -Raw
\ = \ -replace "{conv.status === 'ai_handling' \? 'AI Handled' : conv.status === 'needs_human' \? 'Needs You' : 'Manual'}", "{conv.status === 'limit_reached' ? <Link href={/dashboard/billing} className="text-red-500 font-bold hover:underline">Paused — Limit Reached</Link> : conv.status === 'ai_handling' ? 'AI Handled' : conv.status === 'needs_human' ? 'Needs You' : 'Manual'}"
\ = \ -replace "{activeConversation.status === 'ai_handling' \? 'AI Agent Active' : activeConversation.status === 'needs_human' \? 'Needs You' : 'Manual Mode'} on {activeConversation.channel === 'whatsapp' \? 'WhatsApp' : 'Telegram'}", "{activeConversation.status === 'limit_reached' ? 'Paused — Limit Reached' : activeConversation.status === 'ai_handling' ? 'AI Agent Active' : activeConversation.status === 'needs_human' ? 'Needs You' : 'Manual Mode'} on {activeConversation.channel === 'whatsapp' ? 'WhatsApp' : 'Telegram'}"
Set-Content -Path 'frontend\src\app\dashboard\businesses\[id]\inbox\page.tsx' -Value \ -NoNewline
